var SEEDREV=[
 {name:'Mattias Coopman',stars:5,date:'Google',tr:{"en": "Tobias is fantastic. He has done all my tattoos and is a master of his craft. A very kind person with great stories. I'll be getting many more tattoos from him.", "fr": "Tobias est fantastique. Il a fait tous mes tatouages et c’est un maître dans son métier. Une personne adorable avec de super histoires. Je reviendrai encore très souvent me faire tatouer.", "de": "Tobias ist fantastisch. Er hat alle meine Tattoos gestochen und ist ein Meister seines Fachs. Ein sehr lieber Mensch mit tollen Geschichten. Ich werde noch sehr oft Tattoos bei ihm machen lassen."},text:'Tobias is fantastisch. Hij heeft al mijn tattoos gezet en is een meester in het vak. Enorm lieve mens met geweldige verhalen. Zal er nog heel vaak tattoos laten zetten.'},
 {name:'Michiel Cruysberghs',stars:5,date:'Google',tr:{"en": "Five tattoos by Tobias so far. Tobias is always super friendly, helpful and honest. Top designs, and the healing was always flawless. Top designs of my own or your own inspiration. My future tattoos will be done by Tobias again.", "fr": "Déjà cinq tatouages chez Tobias. Tobias est toujours super sympathique, serviable et honnête. Des designs au top et une cicatrisation toujours impeccable. Des designs au top, de sa propre inspiration ou de la vôtre. Mes prochains tatouages seront à nouveau faits par Tobias.", "de": "Inzwischen fünf Tattoos bei Tobias. Tobias ist immer super freundlich, hilfsbereit und ehrlich. Top-Entwürfe, und die Heilung verlief immer makellos. Top-Entwürfe nach seiner oder eurer eigenen Inspiration. Meine zukünftigen Tattoos werden wieder bei Tobias gestochen."},text:"Ondertussen 5 tattoo's laten zetten bij Tobias. Tobias is altijd super vriendelijk, behulpzaam en eerlijk. Top ontwerpen en de genezing verliep altijd vlekkenloos. Top ontwerpen mij zijn of uw eigen inspiratie. Mijn toekomstige tattoo's zullen weer bij Tobias gezet worden."},
 {name:'Julie Cuyvers',stars:5,date:'Google',tr:{"en": "Tobias recently did my first tattoo, and it was a lovely experience in every way. Tobias thinks along, is patient and takes his time. He did a fantastic job turning the image in my head into a beautiful tattoo. He is professional and at the same time very relaxed, so you feel at ease right away. Thanks Tobias!!", "fr": "Tobias a récemment fait mon premier tatouage, et ce fut une très belle expérience à tous points de vue. Tobias réfléchit avec vous, est patient et prend son temps. Il a réussi de façon fantastique à transformer l’image que j’avais en tête en un magnifique tatouage. Il est professionnel et en même temps très détendu, on se sent tout de suite à l’aise. Merci Tobias !!", "de": "Tobias hat vor Kurzem mein erstes Tattoo gestochen, und das war in jeder Hinsicht eine sehr schöne Erfahrung. Tobias denkt mit, ist geduldig und nimmt sich Zeit. Er hat es fantastisch geschafft, das Bild in meinem Kopf in ein wunderschönes Tattoo zu verwandeln. Er ist professionell und zugleich sehr entspannt, sodass man sich sofort wohlfühlt. Danke Tobias!!"},text:'Tobias heeft onlangs mijn eerste tattoo gezet. En dat was op alle vlakken een heel fijne ervaring. Tobias denkt mee na, is geduldig en neemt zijn tijd. Hij slaagde er fantastisch in om het beeld in mijn hoofd om te zetten naar een prachtige tattoo. Hij is professioneel en tegelijkertijd erg ontspannen waardoor je onmiddellijk op je gemak bent. Bedankt Tobias!!'},
 {name:'Enzo Borremans',stars:5,date:'Google',tr:{"en": "I've been going to Tobias for a few years now. A true craftsman and, on top of that, an interesting and warm person. He takes plenty of time during your appointment to work out the design so it fits perfectly. More than once the end result was much better thanks to his thoughtful feedback. Always healed perfectly, so the final result is flawless. I keep coming back with pleasure.", "fr": "Cela fait déjà quelques années que je vais chez Tobias. Un vrai artisan et, en plus, une personne intéressante et chaleureuse. Il prend largement le temps, lors du rendez-vous, de travailler le design pour qu’il soit parfaitement adapté. Plus d’une fois, le résultat final a été bien meilleur grâce à ses retours réfléchis. Toujours parfaitement cicatrisé, donc un résultat impeccable. Je reviens avec plaisir.", "de": "Ich gehe inzwischen seit einigen Jahren zu Tobias. Ein echter Handwerker und dazu ein interessanter und warmherziger Mensch. Beim Termin nimmt er sich ausgiebig Zeit, den Entwurf auszuarbeiten, damit er ganz nach Maß ist. Mehrmals war das Endergebnis dank seines durchdachten Feedbacks viel besser. Immer perfekt verheilt, sodass das Ergebnis makellos ist. Ich komme gern wieder."},text:'Ondertussen ga ik al enkele jaren bij Tobias. Een echte vakman en daarboven ook een interessant en warm persoon. Hij neemt uitgebreid de tijd op je afspraak om het design uit te werken zodat het helemaal op maat is. Meermaals was het eindproduct veel beter dankzij zijn doordachte feedback. Altijd al perfect genezen waardoor het eindresultaat vlekkeloos is. Ik blijf hier met plezier terugkomen.'},
 {name:'Ronny Van de Velde',stars:5,date:'Google',tr:{"en": "I went to Tobias to have an old tattoo covered. He was on board with my story and what I wanted from the start. The result is a beautiful design I'm extremely happy with. Top experience with a top artist.", "fr": "Je suis allé chez Tobias pour faire recouvrir un ancien tatouage. Dès le début, il a suivi mon histoire et ce que je voulais. Le résultat est un superbe design dont je suis extrêmement satisfait. Une expérience au top avec un artiste au top.", "de": "Ich war bei Tobias, um ein altes Tattoo covern zu lassen. Er hat von Anfang an meine Geschichte und meine Wünsche mitgetragen. Das Ergebnis ist ein toller Entwurf, mit dem ich sehr zufrieden bin. Top-Erfahrung bei einem Top-Artist."},text:'Ik ben bij Tobias geweest om een oude tattoo te laten coveren. Hij was van het begin mee in mijn verhaal en wat ik wou. Dit heeft geresulteerd in een knap ontwerp waar ik enorm tevreden mee ben. Top ervaring bij een top artiest.'},
 {name:'Arnold Verhoeven',stars:5,date:'Google',tr:{"en": "Tobias does the best traditional tattoos, with a twist of his own you won't find anywhere else. Clean lines, strong colours, and years later they still look just as good. On top of that he's a very pleasant person: a full-day session flies by in his calm studio in Borgerhout. He gives honest input on your idea and the placement, without any sales talk. I'm now on my 10th tattoo by Tobias and I keep coming back. Recommended for everyone!", "fr": "Tobias fait les meilleurs tatouages traditionnels, avec une touche personnelle qu’on ne trouve nulle part ailleurs. Des lignes nettes, des couleurs fortes, et des années plus tard ils sont toujours aussi beaux. En plus, c’est une personne très agréable : une séance d’une journée entière passe en un éclair dans son studio calme à Borgerhout. Il réfléchit honnêtement avec vous sur votre idée et le placement, sans discours commercial. J’en suis à mon 10e tatouage chez Tobias et je continue de revenir. À recommander à tout le monde !", "de": "Tobias sticht die besten traditionellen Tattoos, mit einem eigenen Twist, den man nirgendwo anders findet. Klare Linien, starke Farben, und nach Jahren sehen sie noch genauso gut aus. Dazu ist er ein sehr angenehmer Mensch: Eine Tagessession vergeht wie im Flug in seinem ruhigen Studio in Borgerhout. Er denkt ehrlich über deine Idee und die Platzierung mit, ohne Verkaufsgerede. Inzwischen bin ich bei meinem 10. Tattoo bei Tobias und komme immer wieder. Für jeden zu empfehlen!"},text:'Tobias zet de beste traditionele tattoos, met een eigen twist die je nergens anders vindt. Strakke lijnen, sterke kleuren, en na jaren zien ze er nog altijd even goed uit. Daarbij is hij een heel aangename persoon: een sessie van een hele dag vliegt voorbij in zijn rustige studio in Borgerhout. Hij denkt eerlijk mee over je idee en de plaatsing, zonder verkooppraatje. Inmiddels zit ik aan mijn 10e tattoo bij Tobias en ik blijf terugkomen. Een aanrader voor iedereen!'}];
function normalize(st){st.deleted=st.deleted||[];st.rev=st.rev||0;st.reviews=st.reviews||[];st.texts=st.texts||{};
 if(!st.reviews.length&&!st.revSeeded){st.reviews=SEEDREV.map(function(r){return{name:r.name,stars:r.stars,date:r.date,text:r.text,tr:r.tr}});st.revSeeded=true}
 st.reviews.forEach(function(r){if(!r.tr){var sd=SEEDREV.filter(function(x){return x.name===r.name})[0];if(sd)r.tr=sd.tr}});
 st.tags.forEach(function(t){if(!t.g)t.g=t.id.indexOf('a-')===0?'a':(/^y\d|^early$|^recent$/.test(t.id)?'p':'s');if(t.label==='Nature & flowers')t.label='Plants & flowers'});
 st.tags.forEach(function(t){var r=RENAME[(t.label||'').toLowerCase()];if(r)t.label=r});
 var seen={};st.tags=st.tags.filter(function(t){var k=(t.label||'').toLowerCase()+'|'+t.g;if(seen[k]){var keep=seen[k];(st.items||[]).forEach(function(i){i.tags=(i.tags||[]).map(function(x){return x===t.id?keep:x}).filter(function(x,j,a){return a.indexOf(x)===j})});return false}seen[k]=t.id;return true});
 NEWTAGS.forEach(function(n){if(!st.tags.some(function(t){return t.id===n[0]||t.label.toLowerCase()===n[1].toLowerCase()}))st.tags.push({id:n[0],label:n[1],g:n[2]})});
 st.items.forEach(function(i){i.tags=i.tags||[]});return st}
var S=readKey(KEY);
if(S&&(S.rev||0)<SEED.rev){try{localStorage.setItem(KEY+'-backup',JSON.stringify(S))}catch(e){}S=null} /* older than the published tags: keep a safety copy, use the published ones */
