function applyLang(){document.documentElement.lang=LANG;
 [].forEach.call(document.querySelectorAll('[data-i18n]'),function(el){if(!el.dataset.en)el.dataset.en=norm(el.innerHTML);var v=t(el.dataset.en);if(norm(el.innerHTML)!==v)el.innerHTML=v});
 [].forEach.call(document.querySelectorAll('[data-i18n-ph]'),function(el){if(!el.dataset.enph)el.dataset.enph=el.placeholder;el.placeholder=t(el.dataset.enph)});
 [].forEach.call(document.querySelectorAll('[data-i18n-al]'),function(el){if(!el.dataset.enal)el.dataset.enal=el.getAttribute('aria-label');el.setAttribute('aria-label',t(el.dataset.enal))});
 var ls=$('lang');if(ls&&ls.value!==LANG)ls.value=LANG}
