function renderPending(){
 var box=$('a-pend');box.innerHTML='';
 pending.forEach(function(p,ix){
  var r=document.createElement('div');r.className='pend';
  var im=new Image();im.src=p.s;im.alt='Preview of upload';r.appendChild(im);
  var c=document.createElement('div');
  var ti=document.createElement('input');ti.type='text';ti.value=p.t;ti.placeholder='Title, e.g. Panther head';ti.setAttribute('aria-label','Title');ti.oninput=function(){p.t=ti.value};
  c.appendChild(ti);c.appendChild(chips(p.tags));
  var acts=document.createElement('div');acts.className='chips';
  var pub=document.createElement('button');pub.type='button';pub.className='abtn solid';pub.textContent='Publish';
  pub.onclick=function(){pub.disabled=true;pub.textContent='Uploading…';
   uploadPhoto(p.s).then(function(src){S.items.unshift({id:'u'+Date.now().toString(36)+ix,s:src,t:p.t.trim()||'New work',tags:p.tags.slice(),up:1});
    if(!save()){S.items.shift();pub.disabled=false;pub.textContent='Publish';return}pending.splice(ix,1);renderAdm();refresh();toast(ONLINE?'Published — live on every device':'Published in this browser')})
   .catch(function(e){pub.disabled=false;pub.textContent='Publish';toast('Upload failed — '+((e&&e.message)||'check the connection and try again'));console.error('upload',e)})};
  var can=document.createElement('button');can.type='button';can.className='chip del';can.textContent='Cancel';can.onclick=function(){pending.splice(ix,1);renderPending()};
  acts.appendChild(pub);acts.appendChild(can);c.appendChild(acts);r.appendChild(c);box.appendChild(r);
 });
}
function handleFiles(files){
 [].forEach.call(files,function(f){if(!/^image\//.test(f.type))return;
  var rd=new FileReader();rd.onload=function(){var im=new Image();im.onload=function(){
    var m=1100,k=Math.min(1,m/Math.max(im.width,im.height)),cv=document.createElement('canvas');cv.width=Math.round(im.width*k);cv.height=Math.round(im.height*k);
    cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);
    pending.push({s:cv.toDataURL('image/jpeg',.8),t:f.name.replace(/\.[^.]+$/,'').replace(/[-_]+/g,' '),tags:[]});renderPending()};im.src=rd.result};rd.readAsDataURL(f)});
}
var drop=$('a-drop');$('a-file').onchange=function(){handleFiles(this.files);this.value=''};
['dragenter','dragover'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();drop.classList.add('over')})});
['dragleave','drop'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();drop.classList.remove('over')})});
