function hasSubject(i){return i.tags.some(function(id){var t=tagOf(id);return t&&t.g!=='p'})}
function renderAFilter(){
 var box=$('a-filter');box.innerHTML='';
 var opts=[{id:'all',label:'All',n:S.items.length}].concat(S.tags.filter(function(t){return t.g==='s'||t.g==='p'}).map(function(t){return{id:t.id,label:t.label,n:count(t.id,S.items)}}));
 opts.push({id:'none',label:'No subject tag yet',n:S.items.filter(function(i){return!hasSubject(i)}).length});
 opts.forEach(function(o){var c=document.createElement('button');c.type='button';c.className='chip'+(afilter===o.id?' on':'')+(o.id==='none'?' warn':'');c.textContent=o.label+' · '+o.n;
  c.onclick=function(){afilter=o.id;ashown=12;renderAFilter();renderList()};box.appendChild(c)});
 var fc=document.createElement('button');fc.type='button';fc.className='chip'+(afilter==='feat'?' on':'');fc.textContent='★ Hero photos · '+S.items.filter(function(i){return i.feat}).length;fc.onclick=function(){afilter='feat';ashown=12;renderAFilter();renderList()};box.appendChild(fc);
 DROPS.forEach(function(dp){var s=groupSelect(dp[0],S.items,true,dp[1]+': all');s.className='asel big';if((tagOf(afilter)||{}).g===dp[0]){s.value=afilter;s.className+=' on'}
  s.onchange=function(){afilter=s.value||'all';ashown=12;renderAFilter();renderList()};box.appendChild(s)});
}
function renderList(){
 var q=$('a-search').value.trim().toLowerCase(),box=$('a-list');box.innerHTML='';
 var list=S.items.filter(function(i){
  if(afilter==='none'){if(hasSubject(i))return false}else if(afilter==='feat'){if(!i.feat)return false}else if(afilter!=='all'&&i.tags.indexOf(afilter)<0)return false;
  return!q||i.t.toLowerCase().indexOf(q)>-1||i.tags.map(tagLabel).join(' ').toLowerCase().indexOf(q)>-1});
 $('a-count').textContent='('+(list.length===S.items.length?list.length:list.length+' of '+S.items.length)+')';
 list.slice(0,ashown).forEach(function(it){
  var r=document.createElement('div');r.className='arow'+(it.hidden?' hid':'');
  var im=new Image();im.loading='lazy';im.referrerPolicy='no-referrer';im.onerror=function(){if(!im.dataset.f){im.dataset.f=1;im.src=it.s}};im.src=SRC(it.s);im.alt=it.t;r.appendChild(im);
  var c=document.createElement('div');
  if(it.up){var bd=document.createElement('span');bd.className='badge';bd.textContent='New upload';c.appendChild(bd)}
  var ti=document.createElement('input');ti.type='text';ti.value=it.t;ti.draggable=true;ti.ondragstart=function(e){e.preventDefault();e.stopPropagation()};ti.onmousedown=function(e){e.stopPropagation()};ti.setAttribute('aria-label','Title');ti.onchange=function(){it.t=ti.value.trim()||'Untitled';save();toast('Title saved')};
  r.insertBefore(ti,im);
  var sw=document.createElement('div');sw.className='stys';var sl=document.createElement('small');sl.textContent='Subtitle shown under the photo:';sw.appendChild(sl);
  ALT.forEach(function(nm,k){var b=document.createElement('button');b.type='button';b.className='chip'+(it.st===k?' on':'');b.textContent=nm.replace(' traditional tattoo','');b.title=nm;b.onclick=function(){it.st=it.st===k?null:k;save();renderList();refresh()};sw.appendChild(b)});
  var sx=document.createElement('button');sx.type='button';sx.className='chip'+(it.st==null?' on':'');sx.textContent='Own title';sx.title='Use the title in the box above';sx.onclick=function(){it.st=null;save();renderList();refresh()};sw.appendChild(sx);
  c.appendChild(sw);c.appendChild(chips(it.tags,function(){save();renderTags();renderAFilter()}));
  var a=document.createElement('div');a.className='acts';
  var fe=document.createElement('button');fe.type='button';fe.className='chip'+(it.feat?' on':'');fe.textContent=it.feat?'★ Hero':'☆ Hero';fe.title='Show this photo at the top of the homepage (max 6)';
  fe.onclick=function(){if(!it.feat&&S.items.filter(function(x){return x.feat}).length>=6){toast('Six hero photos is the maximum — unstar one first');return}it.feat=!it.feat;save();renderList();renderAFilter();renderHero();toast(it.feat?'Shown on the homepage':'Removed from the homepage')};
  var up=document.createElement('button');up.type='button';up.className='chip';up.textContent='↑';up.title='Move up';up.onclick=function(){var i=S.items.indexOf(it);if(i>0){S.items.splice(i,1);S.items.splice(i-1,0,it);save();renderList();refresh()}};
  var dn=document.createElement('button');dn.type='button';dn.className='chip';dn.textContent='↓';dn.title='Move down';dn.onclick=function(){var i=S.items.indexOf(it);if(i<S.items.length-1){S.items.splice(i,1);S.items.splice(i+1,0,it);save();renderList();refresh()}};
  var tp=document.createElement('button');tp.type='button';tp.className='chip';tp.textContent='⇈ First';tp.title='Move to the front of the gallery';tp.onclick=function(){var i=S.items.indexOf(it);S.items.splice(i,1);S.items.unshift(it);save();renderList();refresh();toast('Moved to the front')};
  var h=document.createElement('button');h.type='button';h.className='chip';h.textContent=it.hidden?'Show':'Hide';h.onclick=function(){it.hidden=!it.hidden;save();renderList();renderHero()};
  var d=document.createElement('button');d.type='button';d.className='chip del';d.textContent='Delete';d.onclick=function(){if(!confirm('Delete "'+it.t+'"?'))return;S.items=S.items.filter(function(x){return x!==it});if(it.s.indexOf('data:')!==0)S.deleted.push(it.s);save();renderAdm();toast('Photo deleted')};
  a.appendChild(fe);a.appendChild(tp);a.appendChild(up);a.appendChild(dn);a.appendChild(h);a.appendChild(d);r.appendChild(c);r.appendChild(a);box.appendChild(r);
  r.draggable=true;r.ondragstart=function(e){DRAG=it;r.classList.add('drag');try{e.dataTransfer.setData('text/plain',it.id||'')}catch(x){}};r.ondragend=function(){DRAG=null;r.classList.remove('drag');[].forEach.call(box.querySelectorAll('.over'),function(x){x.classList.remove('over')})};
  r.ondragover=function(e){if(DRAG&&DRAG!==it){e.preventDefault();r.classList.add('over')}};r.ondragleave=function(){r.classList.remove('over')};
  r.ondrop=function(e){e.preventDefault();if(!DRAG||DRAG===it)return;var from=S.items.indexOf(DRAG),to=S.items.indexOf(it);S.items.splice(from,1);S.items.splice(to,0,DRAG);DRAG=null;save();renderList();refresh();toast('Order saved')};
 });
 $('a-more').parentNode.style.display=list.length>ashown?'flex':'none';
}
