function active(b){ /* does this booking block its slot? */
 if(b.status==='confirmed')return true;
 if(b.status!=='tentative')return false;
 if(!b.date)return true; /* a request without a slot never expires; it blocks nothing */
 return(Date.now()-new Date(b.created).getTime())<AV.holdDays*864e5}
