function parseTimes(str){var out=[];String(str||'').split(/[,;\/\s]+/).forEach(function(t){var m=t.match(/^(\d{1,2})(?:[:.uh](\d{2}))?u?$/i);if(!m)return;var h=+m[1],mi=+(m[2]||0);if(h>23||mi>59)return;var v=pad(h)+':'+pad(mi);if(out.indexOf(v)<0)out.push(v)});return out.sort()}
